package com.rnd.app.service;
import com.rnd.app.entity.*; import com.rnd.app.repository.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class NotificationServiceTest { @Mock NotificationRepository repo; @Mock WorkItemWatcherRepository watchers; @InjectMocks NotificationService service;
 @Test void updatesRecentDuplicate(){Notification n=Notification.builder().id(1L).userId(2L).type("STATUS_CHANGED").workItemId("A").content("old").isRead(true).build();when(repo.findTopByUserIdAndWorkItemIdAndTypeAndCreatedAtAfterOrderByCreatedAtDesc(eq(2L),eq("A"),eq("STATUS_CHANGED"),any())).thenReturn(Optional.of(n));when(repo.save(any())).thenAnswer(i->i.getArgument(0));Notification out=service.notifyDeduplicated(2L,"STATUS_CHANGED","A","new");assertEquals("new",out.getContent());assertFalse(out.getIsRead());}
 @Test void excludesActorFromWatcherNotifications(){when(watchers.findByWorkItemId("A")).thenReturn(List.of(WorkItemWatcher.builder().userId(1L).workItemId("A").build(),WorkItemWatcher.builder().userId(2L).workItemId("A").build()));when(repo.findTopByUserIdAndWorkItemIdAndTypeAndCreatedAtAfterOrderByCreatedAtDesc(eq(2L),eq("A"),eq("COMMENT_ADDED"),any())).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));service.notifyWatchers("A",1L,"COMMENT_ADDED","x");verify(repo).save(argThat(n->n.getUserId().equals(2L)));}
}
